///|
/// TOML parse error type
pub(all) suberror TOMLParseError {
  TOMLParseError(String)
}

///|
fn TOMLParseError::to_string(self : TOMLParseError) -> String {
  match self {
    TOMLParseError(msg) => msg
  }
}

///|
struct Parser {
  input: StringView
  mut pos: Int
  mut line: Int
}

///|
fn Parser::new(input: StringView) -> Parser {
  Parser { input, pos: 0, line: 1 }
}

///|
fn Parser::eof(self: Parser) -> Bool {
  self.pos >= self.input.length()
}

///|
fn Parser::peek(self: Parser) -> Char? {
  if self.eof() { None } else { self.input.get_char(self.pos) }
}

///|
fn Parser::advance(self: Parser) -> Char? {
  let c = self.peek()
  match c {
    Some('\n') => { self.pos = self.pos + 1; self.line = self.line + 1 }
    Some(_) => { self.pos = self.pos + 1 }
    None => ()
  }
  c
}

///|
fn Parser::expect(self: Parser, expected: Char) -> Unit raise TOMLParseError {
  let c = self.advance()
  if c != Some(expected) {
    raise TOMLParseError("Expected '\{expected.to_string()}' at line \{self.line.to_string()}")
  }
}

///|
fn Parser::skip_whitespace(self: Parser) -> Unit {
  loop {
    match self.peek() {
      Some(' ' | '\t') => { self.advance(); continue }
      _ => break
    }
  }
}

///|
fn Parser::skip_rest_of_line(self: Parser) -> Unit {
  loop {
    match self.advance() {
      Some('\n') | None => break
      _ => continue
    }
  }
}

///|
fn Parser::parse_string(self: Parser) -> String raise TOMLParseError {
  self.expect('"')
  let buf = Buffer::new()
  loop {
    match self.advance() {
      Some('"') => break
      Some('\\') => {
        match self.advance() {
          Some('"') => buf.write_byte(b'"')
          Some('\\') => buf.write_byte(b'\\')
          Some('n') => buf.write_byte(b'\n')
          Some('t') => buf.write_byte(b'\t')
          Some(c) => raise TOMLParseError("Invalid escape: \\\{c.to_string()}")
          None => raise TOMLParseError("Unexpected EOF in string escape")
        }
      }
      Some(c) => {
        // Write the char as UTF-8
        buf.write_char_utf8(c)
      }
      None => raise TOMLParseError("Unterminated string")
    }
  }
  buf.to_string()
}
