/// Parse error for TOML parsing
pub(all) suberror TOMLParseError {
  TOMLParseError(String)
}

///|
fn TOMLParseError::to_string(self : TOMLParseError) -> String {
  match self {
    TOMLParseError(msg) => msg
  }
}

///|
struct Parser {
  input: StringView
  mut pos: Int
  mut line: Int
}

///|
fn Parser::new(input: StringView) -> Parser {
  Parser { input, pos: 0, line: 1 }
}

///|
fn Parser::eof(self: Parser) -> Bool {
  self.pos >= self.input.length()
}

///|
fn Parser::peek(self: Parser) -> Char? {
  if self.eof() {
    None
  } else {
    self.input.get_char(self.pos)
  }
}

///|
fn Parser::advance(self: Parser) -> Char? {
  let c = self.peek()
  match c {
    Some('\n') => {
      self.pos = self.pos + 1
      self.line = self.line + 1
    }
    Some(_) => {
      self.pos = self.pos + 1
    }
    None => ()
  }
  c
}

///|
fn Parser::skip_whitespace(self: Parser) -> Unit {
  loop {
    match self.peek() {
      Some(' ' | '\t') => {
        self.advance()
        continue
      }
      _ => break
    }
  }
}

///|
fn Parser::skip_comment(self: Parser) -> Unit {
  // Assumes we're at '#', skip until end of line
  loop {
    match self.advance() {
      Some('\n') | None => break
      _ => continue
    }
  }
}

///|
fn Parser::skip_to_next_line(self: Parser) -> Unit {
  // Skip rest of current line (comment or whitespace)
  loop {
    match self.peek() {
      Some('\n') | None => {
        if !self.eof() {
          self.advance()
        }
        break
      }
      Some('#') => {
        self.skip_comment()
        break
      }
      Some(' ' | '\t') => {
        self.advance()
        continue
      }
      _ => break // non-whitespace, non-comment content remains
    }
  }
}

///|
fn Parser::expect(self: Parser, expected: Char) -> Unit raise TOMLParseError {
  let c = self.advance()
  if c != Some(expected) {
    let actual = match c {
      Some(ch) => ch.to_string()
      None => "EOF"
    }
    raise TOMLParseError(
      "Line \{self.line}: Expected '\{expected.to_string()}', got '\{actual}'",
    )
  }
}

///|
/// Parse a bare key (alphanumeric, dash, underscore)
fn Parser::parse_bare_key(self: Parser) -> String raise TOMLParseError {
  let start = self.pos
  loop {
    match self.peek() {
      Some(c) if c.is_alphanum() || c == '-' || c == '_' => {
        self.advance()
        continue
      }
      _ => break
    }
  }
  if self.pos == start {
    raise TOMLParseError("Line \{self.line}: Expected a key")
  }
  self.input[start:self.pos].to_string()
}

///|
/// Parse a (possibly dotted) key path, e.g. "a.b.c"
fn Parser::parse_key(self: Parser) -> Array[String] raise TOMLParseError {
  let keys = Array::new()
  keys.push(self.parse_bare_key())
  loop {
    self.skip_whitespace()
    match self.peek() {
      Some('.') => {
        self.advance()
        self.skip_whitespace()
        keys.push(self.parse_bare_key())
        continue
      }
      _ => break
    }
  }
  keys
}

///|
/// Parse a string value with escape sequences
fn Parser::parse_string(self: Parser) -> String raise TOMLParseError {
  self.expect('"')
  let buf = Buffer::new()
  loop {
    match self.advance() {
      Some('"') => break
      Some('\\') => {
        match self.advance() {
          Some('"') => buf.write_char_utf8('"')
          Some('\\') => buf.write_char_utf8('\\')
          Some('n') => buf.write_char_utf8('\n')
          Some('t') => buf.write_char_utf8('\t')
          Some(c) =>
            raise TOMLParseError(
              "Line \{self.line}: Invalid escape sequence: \\\{c.to_string()}",
            )
          None =>
            raise TOMLParseError(
              "Line \{self.line}: Unexpected EOF in string escape sequence",
            )
        }
      }
      Some(c) => buf.write_char_utf8(c)
      None => raise TOMLParseError("Line \{self.line}: Unterminated string")
    }
  }
  buf.to_string()
}

///|
/// Parse an integer (optionally signed)
fn Parser::parse_int(self: Parser) -> Int raise TOMLParseError {
  let start = self.pos
  match self.peek() {
    Some('+' | '-') => {
      self.advance()
    }
    _ => ()
  }
  loop {
    match self.peek() {
      Some(c) if c.is_digit() => {
        self.advance()
        continue
      }
      _ => break
    }
  }
  if self.pos == start {
    raise TOMLParseError("Line \{self.line}: Expected an integer")
  }
  let s = self.input[start:self.pos].to_string()
  match Int::from_string(s) {
    Ok(v) => v
    Err(_) => raise TOMLParseError("Line \{self.line}: Invalid integer: '\{s}'")
  }
}

///|
/// Parse a boolean (true or false)
fn Parser::parse_bool(self: Parser) -> Bool raise TOMLParseError {
  let start = self.pos
  loop {
    match self.peek() {
      Some(c) if c.is_alphabetic() => {
        self.advance()
        continue
      }
      _ => break
    }
  }
  let s = self.input[start:self.pos].to_string()
  match s {
    "true" => true
    "false" => false
    _ =>
      raise TOMLParseError(
        "Line \{self.line}: Invalid boolean: '\{s}' (expected 'true' or 'false')",
      )
  }
}

///|
/// Parse an array value
fn Parser::parse_array(self: Parser) -> Array[Json] raise TOMLParseError {
  self.expect('[')
  self.skip_whitespace()
  let items = Array::new()
  // Check for empty array
  match self.peek() {
    Some(']') => {
      self.advance()
      return items
    }
    _ => ()
  }
  loop {
    self.skip_whitespace()
    let value = self.parse_value()
    items.push(value)
    self.skip_whitespace()
    match self.peek() {
      Some(',') => {
        self.advance()
        self.skip_whitespace()
        continue
      }
      Some(']') => {
        self.advance()
        break
      }
      Some(c) =>
        raise TOMLParseError(
          "Line \{self.line}: Expected ',' or ']' in array, got '\{c.to_string()}'",
        )
      None => raise TOMLParseError("Line \{self.line}: Unterminated array")
    }
  }
  items
}

///|
/// Parse a value (string, int, bool, or array)
fn Parser::parse_value(self: Parser) -> Json raise TOMLParseError {
  self.skip_whitespace()
  match self.peek() {
    Some('"') => Json::string(self.parse_string())
    Some('t' | 'f') => Json::boolean(self.parse_bool())
    Some('[') => Json::array(self.parse_array())
    Some('+' | '-') | Some(c) if c.is_digit() => {
      // Check if it's an integer (followed by whitespace, comma, ], newline, or EOF)
      let saved = self.pos
      let val = self.parse_int()
      Json::number(val.to_double())
    }
    Some(c) =>
      raise TOMLParseError(
        "Line \{self.line}: Unexpected character '\{c.to_string()}'",
      )
    None => raise TOMLParseError("Line \{self.line}: Unexpected EOF")
  }
}

///|
/// Set a value at a dotted key path in a map, creating nested objects as needed.
fn set_nested_value(map: Map[String, Json], keys: ArrayView[String], value: Json) -> Unit raise TOMLParseError {
  fn helper(m: Map[String, Json], idx: Int) -> Unit raise TOMLParseError {
    let key = keys[idx]
    if idx == keys.length() - 1 {
      // Last key - set the value
      if m.contains(key) {
        raise TOMLParseError("Duplicate key: '\{keys.join(".")}'")
      }
      m[key] = value
    } else {
      // Intermediate key - ensure there's a nested object
      if m.contains(key) {
        match m[key] {
          Json::Object(nested) => helper(nested, idx + 1)
          _ => raise TOMLParseError("Key '\{key}' is not a table and cannot be extended")
        }
      } else {
        let nested: Map[String, Json] = {}
        m[key] = Json::object(nested)
        helper(nested, idx + 1)
      }
    }
  }
  helper(map, 0)
}

///|
/// Navigate to a table path, creating nested objects as needed.
/// Returns the map for the last segment.
fn navigate_to_table(root: Map[String, Json], path: ArrayView[String]) -> Map[String, Json] raise TOMLParseError {
  let mut current = root
  for i in 0..<path.length() {
    let key = path[i]
    if i == path.length() - 1 {
      // Last segment: this is the table itself
      if current.contains(key) {
        match current[key] {
          Json::Object(_) => {
            // Table already exists - that's a duplicate in TOML (allowed for dotted tables but let's be strict)
            // Actually in TOML, [owner] and [owner] is an error, but [a.b] and [a.b] is also an error.
            // Let me re-check... Actually TOML allows multiple sections with the same table header,
            // like [owner] can appear multiple times. But for simplicity, let's be strict.
            raise TOMLParseError("Duplicate table: '\{path.join(".")}'")
          }
          _ => raise TOMLParseError("Key '\{key}' is not a table")
        }
      } else {
        let nested: Map[String, Json] = {}
        current[key] = Json::object(nested)
      }
      match current[key] {
        Json::Object(m) => return m
        _ => raise TOMLParseError("Expected object at '\{key}'")
      }
    } else {
      // Intermediate segment
      if current.contains(key) {
        match current[key] {
          Json::Object(m) => current = m
          _ => raise TOMLParseError("Key '\{key}' is not a table")
        }
      } else {
        let nested: Map[String, Json] = {}
        current[key] = Json::object(nested)
        current = nested
      }
    }
  }
  // Should not reach here
  current
}

///|
/// Skip any blank lines and comments at the current position
fn Parser::skip_blank_and_comments(self: Parser) -> Unit {
  loop {
    self.skip_whitespace()
    match self.peek() {
      Some('#') => {
        self.skip_comment()
        continue
      }
      Some('\n') => {
        self.advance()
        continue
      }
      None | Some(_) => break
    }
  }
}

///|
/// Main TOML parsing entry point
pub fn parse_toml(input: StringView) -> Json raise TOMLParseError {
  let parser = Parser::new(input)
  let root: Map[String, Json] = {}
  let mut current_table: Map[String, Json] = root

  parser.skip_blank_and_comments()

  while !parser.eof() {
    // Check for table header
    parser.skip_whitespace()
    match parser.peek() {
      Some('[') => {
        parser.advance() // consume first '['
        // Check for [[ (array of tables) - not supported
        match parser.peek() {
          Some('[') =>
            raise TOMLParseError(
              "Line \{parser.line}: Array of tables ([[...]]) is not supported",
            )
          _ => ()
        }
        parser.skip_whitespace()
        let table_path = parser.parse_key()
        parser.skip_whitespace()
        parser.expect(']')
        parser.skip_to_next_line()
        current_table = navigate_to_table(root, table_path)
        parser.skip_blank_and_comments()
        continue
      }
      _ => ()
    }

    // Otherwise it's a key-value pair
    parser.skip_whitespace()
    let keys = parser.parse_key()
    parser.skip_whitespace()
    parser.expect('=')
    parser.skip_whitespace()
    let value = parser.parse_value()
    parser.skip_whitespace()
    // Skip trailing comment or newline
    parser.skip_to_next_line()
    parser.skip_blank_and_comments()

    // Set the value in the current table
    set_nested_value(current_table, keys, value)
  }

  Json::object(root)
}
"}

